/**
 * Draft collection schema for the experimental query builder.
 * The live `Project` and `Blog` schemas are in `~/server/db`.
 */

import * as v from "valibot"
import { Collections, non_nullable_for_falsies, nullable_for_falsies, RelationSpec } from "./lib";

// should be auto-generated by rust
const project_schema = v.object({
    title: non_nullable_for_falsies(v.string()),
    content: non_nullable_for_falsies(v.string()),
    summary: non_nullable_for_falsies(v.string()),
    github_link: nullable_for_falsies(v.string()),
    live_link: nullable_for_falsies(v.string()),
    created_at: v.pipe(v.string(), v.isoTimestamp()),
    display_picture: nullable_for_falsies(v.string()),
    skills: nullable_for_falsies(v.string()),
});

export const links = {
    "relation": (self: { from: string, to: string }, { by_id }: { by_id: number }) => {
        throw new Error("no relations defined")
    },
} as const satisfies Record<string, RelationSpec>

export const collections = {
    project: {
        schema: project_schema,
        select: (by_id) => {
            return `
         SELECT 
             id as id,
             title as title,
             content as content,
             summary as summary,
             github_link as github_link,
             live_link as live_link,
             created_at as created_at,
             display_picture as display_picture,
             skills as skills
         FROM Project
         WHERE id = ?;
        ` },
        relation: {}
    },
} as const satisfies Collections
